source_script:
# Exact precise role consumer test-artifact cleanup. No recursive directory removal.
$ErrorActionPreference = 'Stop'
$plan = Get-Content -LiteralPath 'C:\public\project-hyle\hyle\.scratch\architecture-refactor-2026-10-18\precise-role-consumers-2026-10-21\root\cleanup-plan.json' -Raw | ConvertFrom-Json
$separator = [IO.Path]::DirectorySeparatorChar
$allowed = [IO.Path]::GetFullPath($plan.allowed_windows).TrimEnd($separator) + $separator
function Assert-Identity($row) {
  $file = Get-Item -LiteralPath $row.path -ErrorAction Stop
  if ($file.PSIsContainer -or ($file.Attributes -band [IO.FileAttributes]::ReparsePoint)) { throw "Not a regular file: $($row.path)" }
  if ($file.Length -ne $row.bytes -or (Get-FileHash -LiteralPath $row.path -Algorithm SHA256).Hash.ToLowerInvariant() -ne $row.sha256) { throw "Identity changed: $($row.path)" }
}
Assert-Identity $plan.evidence
Assert-Identity $plan.archive
foreach ($row in $plan.remove_windows) {
  $full = [IO.Path]::GetFullPath($row.path)
  if (-not $full.StartsWith($allowed, [StringComparison]::OrdinalIgnoreCase) -or [IO.Path]::GetExtension($full) -notin '.exe','.map') { throw "Outside exact artifact scope: $full" }
  Assert-Identity $row
}
foreach ($row in $plan.keep_windows) { Assert-Identity $row }
$active = @(Get-CimInstance Win32_Process | Where-Object { $_.ExecutablePath -and $_.ExecutablePath.StartsWith($allowed, [StringComparison]::OrdinalIgnoreCase) })
if ($active.Count) { throw 'A test executable in this exact workspace is still running' }
foreach ($row in $plan.remove_windows) { Remove-Item -LiteralPath $row.path -Force }
foreach ($row in $plan.keep_windows) { Assert-Identity $row }
$macProgram = @'
import pathlib,hashlib,json,subprocess
plan=json.loads('{"allowed_mac": "/Users/kiro/hyle-scratch/compute-unified/architecture-refactor-20261019-apple-page-invocation/precise-role-consumers-2026-10-21/apple", "remove_mac": [{"path": "/Users/kiro/hyle-scratch/compute-unified/architecture-refactor-20261019-apple-page-invocation/precise-role-consumers-2026-10-21/apple/mlx-moe-complete", "bytes": 16816464, "sha256": "30cfca9e95ab499eb25cd9a8269e5de11fbc4f309a4916f68b15a860ada6a664"}, {"path": "/Users/kiro/hyle-scratch/compute-unified/architecture-refactor-20261019-apple-page-invocation/precise-role-consumers-2026-10-21/apple/mlx-moe-complete.map", "bytes": 4987149, "sha256": "902d101ebaf83193cdc54db6466b9123eca711ddd94b1e6416156a923d154f9d"}, {"path": "/Users/kiro/hyle-scratch/compute-unified/architecture-refactor-20261019-apple-page-invocation/precise-role-consumers-2026-10-21/apple/precise-role-consumers", "bytes": 16835720, "sha256": "93d636ac29ca4702ac429ea226d914b78c8bfa938dca729ffd58bcdd110e6904"}, {"path": "/Users/kiro/hyle-scratch/compute-unified/architecture-refactor-20261019-apple-page-invocation/precise-role-consumers-2026-10-21/apple/precise-role-consumers.map", "bytes": 4990462, "sha256": "ab70ed9f5c57d753ee029af5248073bef6319c20b1defa0a0ef641c38295d263"}], "keep_mac": [{"path": "/Users/kiro/hyle-scratch/compute-unified/architecture-refactor-20261019-apple-page-invocation/precise-role-consumers-2026-10-21/apple/objects/src--compute--weight_import.cc.o", "bytes": 28776, "sha256": "b01eeb2c89bf0f1864afbfd0874415270b6d455aa651348b6b70e9f7dd9978b8"}, {"path": "/Users/kiro/hyle-scratch/compute-unified/architecture-refactor-20261019-apple-page-invocation/precise-role-consumers-2026-10-21/apple/objects/tests--graph_route_apple--e8m0_weight_import_test.cc.o", "bytes": 169392, "sha256": "b27fb6fcff4636978da2a5744acff3607263331c6c21fd49545356d8a1361c50"}, {"path": "/Users/kiro/hyle-scratch/compute-unified/architecture-refactor-20261019-apple-page-invocation/precise-role-consumers-2026-10-21/apple/objects/tests--graph_route_apple--mlx_moe_test.cc.o", "bytes": 185104, "sha256": "f0b088e6bf1b9fa40a19b2c1203f4df13ed59c5d127637e8f703e687ef9a192c"}]}')
base=pathlib.Path(plan['allowed_mac']); assert base.is_dir() and not base.is_symlink()
def verify(row):
 p=pathlib.Path(row['path']); assert p.is_absolute() and not p.is_symlink() and p.resolve().is_relative_to(base.resolve())
 assert p.is_file() and p.stat().st_size==row['bytes'] and hashlib.sha256(p.read_bytes()).hexdigest()==row['sha256'],str(p)
 return p
paths=[verify(x) for x in plan['remove_mac']]
for row in plan['keep_mac']:verify(row)
active=subprocess.check_output(['ps','-axo','command='],text=True)
assert not any(str(p) in command for p in paths for command in active.splitlines() if not command.startswith('python3 -')), 'test executable is running'
for p in paths:p.unlink()
for row in plan['keep_mac']:verify(row)
print(json.dumps(dict(removed=len(paths),bytes=sum(x['bytes'] for x in plan['remove_mac']),kept_objects=len(plan['keep_mac']))))
'@
$macResult = $macProgram | & ssh kiro@172.22.10.198 python3 -
if ($LASTEXITCODE -ne 0) { throw 'Mac exact-file cleanup failed; do not report both platforms completed' }
$result = [ordered]@{
  completed = $true
  windows_removed = @($plan.remove_windows).Count
  windows_bytes = ($plan.remove_windows | Measure-Object -Property bytes -Sum).Sum
  windows_kept_objects = @($plan.keep_windows).Count
  mac = ($macResult | ConvertFrom-Json)
  evidence_sha256 = $plan.evidence.sha256
  archive_sha256 = $plan.archive.sha256
  exact_plan = $plan
  source_script = [IO.File]::ReadAllText($PSCommandPath)
}
$result | ConvertTo-Json -Depth 18 | Set-Content -LiteralPath 'C:\public\project-hyle\hyle\docs\evidence\correctness\precise-role-consumers-reference-2026-10-21.cleanup.json' -Encoding utf8
[pscustomobject]$result | Select-Object completed,windows_removed,windows_bytes,windows_kept_objects,mac | ConvertTo-Json -Depth 5
